    const int tid = (tq * blockDim.y + ty) * blockDim.x + tx;
    const int ox0 = static_cast<int>(blockIdx.x) * blockDim.x;
    const int oy0 = static_cast<int>(blockIdx.y) * blockDim.y;
    const int ox = ox0 + tx;
    const int oy = oy0 + ty;
    const int z = static_cast<int>(blockIdx.z);
    const int oz = z % OD;
    const int oc_tiles_per_group = (OC_per_group + 4 - 1) / 4;
    const int tile_id = z / OD;
    const int n = tile_id / (groups * oc_tiles_per_group);
    const int group_tile = tile_id % (groups * oc_tiles_per_group);
    const int group = group_tile / oc_tiles_per_group;
    const int oc_tile = group_tile % oc_tiles_per_group;
    const int oc_local = oc_tile * 4 + tq;
    const int base_y = floor_div_int(
        oy0 + pad_h - (KH - 1) * dil_h, stride_h);
    const int base_x = floor_div_int(
        ox0 + pad_w - (KW - 1) * dil_w, stride_w);
    const int smem_elems = IC_per_group * tile_h * tile_w;
    const bool active = ox < OW && oy < OH && n < N &&
                        oc_local < OC_per_group;
    float acc = (active && bias != nullptr)
        ? bias[group * OC_per_group + oc_local]
        : 0.0f;
    for (int kz = 0; kz < KD; ++kz) {
        for (int linear = tid; linear < smem_elems;
             linear += blockDim.x * blockDim.y * blockDim.z) {
            int t = linear;
            const int sx = t % tile_w;
            t /= tile_w;
            const int sy = t % tile_h;
            t /= tile_h;
            const int ic_local = t;
            const int tz_in = oz + pad_d - kz * dil_d;
            const bool valid_z =
                tz_in >= 0 && (tz_in % stride_d) == 0 &&
                (tz_in / stride_d) < ID;
            const int iz = tz_in / stride_d;
            const int iy = base_y + sy;
            const int ix = base_x + sx;
            const bool valid_xy =
                iy >= 0 && iy < IH && ix >= 0 && ix < IW;
            float value = 0.0f;
            if (valid_z && valid_xy && n < N) {
                const int ic = group * IC_per_group + ic_local;
                const int64_t x_idx =
                    (((static_cast<int64_t>(n) * IC + ic) * ID + iz) * IH + iy) * IW + ix;
                value = x[x_idx];
            }
            smem[(ic_local * tile_h + sy) * tile_w + sx] = value;
        }
        __syncthreads();
        if (active) {
            const int tz_in = oz + pad_d - kz * dil_d;
            if (tz_in >= 0 && (tz_in % stride_d) == 0) {
                const int iz = tz_in / stride_d;
                if (iz >= 0 && iz < ID) {
                    for (int ky = 0; ky < KH; ++ky) {
                        const int ty_in = oy + pad_h - ky * dil_h;
                        if (ty_in < 0 || (ty_in % stride_h) != 0) {
                            continue;
                        }
                        const int iy = ty_in / stride_h;
                        if (iy < 0 || iy >= IH) {
                            continue;
                        }
                        const int sy = iy - base_y;
                        for (int kx = 0; kx < KW; ++kx) {
                            const int tx_in = ox + pad_w - kx * dil_w;
                            if (tx_in < 0 || (tx_in % stride_w) != 0) {
                                continue;
                            }
                            const int ix = tx_in / stride_w;
                            if (ix < 0 || ix >= IW) {
                                continue;
                            }
                            const int sx = ix - base_x;
                            if (sy < 0 || sy >= tile_h ||
                                sx < 0 || sx >= tile_w) {
                                continue;
                            }
                            for (int ic_local = 0;
                                 ic_local < IC_per_group; ++ic_local) {
                                const int ic = group * IC_per_group + ic_local;
                                const float input_value =
                                    smem[(ic_local * tile_h + sy) * tile_w + sx];
                                const int64_t w_idx =
                                    ((((static_cast<int64_t>(ic) * OC_per_group + oc_local) * KD + kz)
                                      * KH + ky) * KW + kx);
                                acc += input_value * weight[w_idx];
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    if (active) {
        const int ocl = group * OC_per_group + oc_local;
        const int64_t out_idx =
            (((static_cast<int64_t>(n) * OC + ocl) * OD + oz) * OH + oy) * OW + ox;
        out[out_idx] = acc;
    }
}

